// ---------- Navigation ----------
function navigate(hash) {
  const path = hash.replace(/^#\//, '').replace(/^#/, '');
  const parts = path.split('/').filter(Boolean);

  if (parts.length === 2) {
    // /category/tool-id
    const catKey = parts[0];
    const toolId = parts[1];
    const cat = CALC_DATA[catKey];
    if (cat) {
      const tool = cat.tools.find(t => t.id === toolId);
      if (tool) { renderTool(catKey, tool); return; }
    }
  }
  if (parts.length === 1 && parts[0]) {
    const catKey = parts[0];
    if (CALC_DATA[catKey]) { renderCategory(catKey); return; }
    if (STATIC_PAGES[catKey]) { renderStatic(catKey); return; }
  }
  if (!path || path === '') { renderHome(); return; }
  renderStatic('404');
}

