  // Find the tool in any category
  for (const [key, cat] of Object.entries(CALC_DATA)) {
    if (cat.tools.some(t => t.id === toolId)) {
      window.location.hash = '#/' + key + '/' + toolId;
      return;
    }
  }
  showToast('Calculator not found');
}

