    }).catch(function () { _legacyCopy(text); });
  } else {
    _legacyCopy(text);
  }
}
function _legacyCopy(text) {
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
